/* Included once, by arr.c. Style s's patterns are pattern numbers ARR_FACTORY0 + 6s + section (Intro, Main
 * A, Main B, Fill AB, Fill BA, Ending; a section not written: no notes). An event (480 ticks a beat): tick | note << 15 | the length code's low 10 bits << 22
 * (STY_EV); its velocity | the code's 11th bit << 7 (STY_VEL). The code: lengths 1..1020 exact (code 0..1019),
 * longer ones in steps of 20 ticks (sty_len). */
#pragma once
#include <stdint.h>

typedef struct {
    uint8_t program, chan, type, lo, hi, hikey, vol, pan, rev, cho, mute, rsv;
    uint16_t count;                      /* its events, after the previous track's */
} sty_trk_t;
typedef struct {
    uint8_t bars, beats;
    uint16_t first;                      /* its first event in STY_EV */
    sty_trk_t trk[8];
} sty_pat_t;
static inline uint32_t sty_len(uint32_t c) { return c < 1020u ? c + 1u : 1020u + (c - 1019u) * 20u; }

